# -*- coding: utf-8 -*-
"""矛盾驱动补盲 · 批次C9（v7 新域 8 簇+直答）"""
def patch(path):
    src = open(path, encoding="utf-8").read()
    anchor_c = '    "概念形成": ["概念形成", "原型理论", "样例理论", "概念是怎么形成的"],'
    new_c = '''    "军备竞赛": ["军备竞赛", "军费花这么多", "军费值吗", "和平是打出来",
                "谈出来的", "军备怎么停", "军费和民生", "扩军", "军费开支",
                "军事开支", "武器竞赛", "为什么扩军"],
    "代理人战争": ["代理人战争", "大国打仗借手", "不下场", "避免大战",
                  "小国选边", "大国博弈自保", "代理人", "借别人的手",
                  "小国自保", "选边站"],
    "宗教传统": ["传统和现代冲突", "传统习俗保留", "老祖宗的东西", "不能丢",
                "传统都是糟粕", "全丢", "精华和糟粕", "传统和现代共存",
                "传统习俗", "传统文化", "老规矩"],
    "太空探索": ["抢着登月", "探火", "太空探索花钱", "太空值吗", "地球上问题",
                "搞太空", "太空资源", "殖民地争夺", "太空开发合作",
                "太空探索意义", "登月", "火星"],
    "碳税": ["为什么要收碳税", "碳交易变相收钱", "碳税企业负担", "碳税公平",
            "碳中和出力", "碳税", "碳交易", "碳排放配额", "碳市场",
            "减排成本", "碳价"],
    "元宇宙": ["虚拟身份现实身份", "哪个是真的", "虚拟世界也是一种生活",
              "元宇宙泡沫", "虚拟现实平衡", "元宇宙孤独", "元宇宙",
              "虚拟世界", "数字身份", "虚拟人生"],
    "基因编辑": ["基因编辑治病变态", "基因编辑婴儿禁止", "能治绝症放开",
                "医疗优生学划界", "基因编辑", "编辑基因", "CRISPR",
                "基因治疗", "设计婴儿", "优生学"],
    "脑机接口": ["脑机接口福音风险", "芯片装进大脑", "能治瘫痪推进",
                "思想被读取", "脑机接口发展", "意识和技术", "脑机接口",
                "大脑芯片", "神经接口", "读脑", "意念控制"],'''
    assert anchor_c in src
    src = src.replace(anchor_c, new_c + "\n    " + anchor_c, 1)

    anchor_d = '    "概念形成": "概念形成是人获得概念的方式——原型理论（典型样例）、样例理论（具体实例）、理论观（嵌入知识网络）；对应知识卡组织",'
    new_d = '''    "军备竞赛": "国家搞军备竞赛，是『安全困境』的必然——我扩军是自卫，但在对方眼里是威胁，对方也扩军，结果双方军备都涨但谁都不更安全（安全困境：追求安全的行动反而降低安全）。真相：①军费值不值——从安全看值（威慑防入侵），从民生看贵（军费挤占教育医疗），各国都在平衡；②『和平是打出来还是谈出来』——都有：威慑（能打而不打）让对手不敢打，谈判（共同利益）让冲突有出口，只谈不备是裸奔，只备不谈是战争边缘；③军备竞赛怎么停——单方停会被欺负（囚徒困境），需要军控条约（互相监督削减）+ 信任建设（透明度/热线），冷战美苏军控是成功案例。军费和民生平衡：安全是民生前提（没安全谈何发展），但军费占比有上限（超GDP的3-4%会拖垮经济），『够用威慑』优于『无限扩张』——最安全的不是军备最多，是让对手算不清你的底牌又不敢轻举妄动",
    "代理人战争": "大国打仗借别人的手（代理人战争），是『避免直接冲突』的战略选择——核大国直接开战=互相毁灭（古巴导弹危机教训），所以用代理人（扶持一方）实现博弈目的，自己不流血。真相：①为什么不下场——直接开战风险太高（升级失控），代理人战争是『可控的对抗』（打了也不至于全面战争）；②代理人战争苦了谁——最苦的是战场上的小国人民：大国在别人国土上博弈，死的是当地的兵、毁的是当地的家，战后大国撤了，废墟留下；③小国是不是只能选边站——不完全：有第三条路（不结盟/等距外交/当调停者），但确实难（大国施压下中立要实力和智慧）。避免代理人战争的出路：①大国克制——博弈回到谈判桌（外交/经济），别把冲突外包到小国；②国际机制——联合国/区域组织调停，冲突规范化（定规则不打平民）；③小国自保——不选边的本钱：内政稳（别被颠覆）、外交活（两边都处好）、军事够用（自保威慑）。核心：代理人战争是弱者的悲剧——大国要自律，小国要自强",
    "宗教传统": "传统和现代生活冲突，是『传承需要』vs『时代变化』的矛盾——传统承载认同（习俗/伦理/记忆），但有些传统与平等/自由/科学冲突（重男轻女/迷信/人身束缚）。真相：①传统该不该保留——该：传统是文化根脉（没了传统的人会迷茫），但『保留』不等于『原样照搬』——传统是活的东西，一直在变（今天的『传统』也是过去的『现代』演化来的）；②『老祖宗的东西不能丢』——情感正确但需要辨析：丢的是『形式』还是『精神』？比如春节的形式在变（不放鞭炮了），精神（团圆）还在——守住精神，形式可以变；③『传统都是糟粕』——同样偏激：传统里有糟粕（等级/迷信）也有精华（孝道/勤俭/家国情怀），全盘否定等于丢根。区分精华和糟粕的标准：①是否尊重人（平等的保留，压迫的剔除）；②是否经得起检验（科学的保留，迷信的剔除）；③是否服务当下（有用的保留，纯形式的可简化）。共存之道：『创造性转化』——把传统精神用现代形式表达（清明用鲜花代替烧纸、家训变成现代家规），传统不是包袱是资源",
    "太空探索": "各国抢着登月探火，是『国家实力象征』+『战略资源争夺』+『科学好奇』的三重驱动——航天是综合国力的橱窗（技术/资金/组织能力），月球/火星有资源（氦-3/稀土/水冰）和战略位置（深空中转站）。真相：①『地球上问题都没解决搞太空干嘛』——太空探索不是和地球问题二选一：航天投入占GDP极小（中国约0.5%），却带动大量技术（卫星通信/导航/材料）反哺地面，『搞太空』和『解决地球问题』不冲突；②太空是不是新殖民地争夺——是隐患：各国抢轨道/频谱/月球资源，有『圈地』趋势（先到先得），目前国际太空法滞后（1967年条约规定太空为人类共有，但没执行机制）；③太空探索值不值——从投入产出看值：GPS/气象/通信都来自太空投入，更不用说科学发现（宇宙认知）。合作与竞争的平衡：①科学合作（国际空间站/深空探测共享数据）——科学无国界；②资源规则（月球开发要立约：谁开发谁受益但要公示/别垄断）——避免太空军备竞赛；③意义——太空探索是人类『往外看』的本能，也是文明的保险（地球不是永远安全）。核心：太空是下一个边疆——既要竞争（实力）也要规则（秩序），别把地球的冲突带上天",
    "碳税": "收碳税，是『让排放者付费』的经济手段——碳排放造成气候损失（外部性），但过去没人付钱（免费污染），碳税让排放成本内部化（排得越多付得越多），用价格杠杆推动减排。真相：①碳交易是不是变相收钱——半真：碳市场确实是『收钱』（企业买配额），但收的钱用于减排（补贴绿色技术/植树），且『配额总量控制』真的减少排放（总量逐年降=排放逐年降），不是单纯收税；②碳税是不是给企业加负担——短期是：高耗能企业成本上升（可能裁员/涨价），长期是倒逼转型（节能省下的钱>碳税支出）；③发达国家的碳税——更早更多（欧盟碳市场全球最大），但『历史排放』该谁买单的争议还在（发达国家排了两百年）。公平收碳税三原则：①循序渐进——先低税率后逐步提（给企业转型时间），突然重税会休克；②收入返还——碳税收入用于补贴低收入家庭（碳税是累退税，穷人负担比例高，要返还平衡）；③全球协调——单国收碳税会让企业外逃（碳泄漏），需要边境碳税（进口也收）协调。个人出力：不是只有大企业的事——少开车/少用空调/少浪费（消费降碳），个人碳足迹累积起来很可观",
    "元宇宙": "虚拟身份和现实身份哪个是真的、元宇宙会不会让人更孤独，是『虚拟体验』vs『现实根基』的矛盾——元宇宙提供即时满足（想成为谁都行/社交无压力），现实有真实连接也有真实痛苦。真相：①虚拟世界也是一种生活吗——是也不是：虚拟体验是真实的情感体验（游戏里的友谊/成就感是真的），但虚拟关系的脆弱性也是真的（关服务器就消失/对方随时消失）；②哪个身份是真的——都真：虚拟身份是现实自我的投射/补充（你可能在虚拟里展示现实不敢展示的一面），但『真实』的定义在于责任（现实的你为虚拟的你负责）；③元宇宙孤独——风险真实：沉溺虚拟社交（点赞/组队）替代现实连接（面对面/深聊），『看似热闹实则孤独』（虚拟社交是浅连接，替代不了深度关系）。健康使用三原则：①时间边界——虚拟是生活的一部分不是全部（占比<30%），定闹钟防沉溺；②把虚拟当工具不当替代——用虚拟学习/创作/远距离联系，不用它逃避现实问题（逃避的坑会越逃越深）；③锚定现实——虚拟身份再精彩，也要回到现实生活（吃饭/运动/真实朋友），现实是根，虚拟是叶。核心：虚拟世界是新的生活空间，但别忘了——生活的主场在现实，虚拟是工具不是归宿",
    "基因编辑": "基因编辑（CRISPR）是治病希望也是伦理雷区——能精准修改基因（治遗传病/癌症），也能被滥用（设计婴儿/优生学）。真相：①为什么治病变态还被警惕——技术本身中性，风险在『应用边界』：治病（体细胞编辑，只改本人，安全可控）和设计后代（生殖细胞编辑，改遗传给下一代，影响不可逆且涉及后代选择权）是两回事——治病是治疗，设计是改造；②基因编辑婴儿为什么被禁——多重原因：技术不成熟（脱靶风险/未知后果）、伦理越界（孩子没同意就被改）、滑向优生学（基因决定论：筛选'优良'基因=歧视'劣质'人，纳粹优生学的阴影）；③能治绝症为什么不放开——放开的是『体细胞治疗』（已用于镰刀贫血等），不放的是『生殖编辑』（安全+伦理都没准备好）。划界原则：①治疗优先——治病的放开（患者本人受益），增强的谨慎（健康人'强化'基因=制造不平等）；②可逆性——编辑要可逆/可监测（别一锤子买卖）；③共识程序——重大应用要伦理委员会/公众讨论（不是少数科学家说了算）。核心：基因编辑是双刃剑——治病救人要用，改造人类要慎，边界在『治疗』与『设计』之间",
    "脑机接口": "脑机接口（把芯片装进大脑）是瘫痪者的福音也是隐私的噩梦——能读取大脑信号（让瘫痪者用意念打字/控制轮椅），也能被滥用（思想被读取/意识被操控）。真相：①福音是真的——脑机接口已帮渐冻症患者'意念打字'、帮瘫痪者控制机械臂，这是实打实的技术突破（不是科幻）；②风险也是真的——大脑是最后的隐私阵地：读取大脑信号（现在只能读'意图'，未来可能读'情绪/偏好'）一旦数据泄露/被操控，人是被'黑客'的（想法都被监控），而且侵入性手术有感染/损伤风险；③『能治瘫痪为什么不全力推进』——要推进但分步：先侵入性低的方式（头戴式/植入浅层），再逐步深入，安全>速度（大脑伤不起，坏了不能重来）。发展三原则：①医疗优先——先用于治病（瘫痪/失明/癫痫），后谈增强（健康人'增强智力'，伦理争议大）；②数据主权——脑数据是最高级隐私：采集要明确同意/加密存储/禁止商业滥用（脑数据卖给广告商=灾难）；③人机边界——技术辅助人而不是替代人（脑机接口帮人恢复功能，不是让人成为'半机器'），意识和技术的关系：技术可以读取/辅助意识，但不能定义/取代意识——人之所以为人，在技术之外还有自主和尊严。核心：脑机接口要慢慢来——医疗的用，增强的慎，隐私的守",
    "概念形成": "概念形成是人获得概念的方式——原型理论（典型样例）、样例理论（具体实例）、理论观（嵌入知识网络）；对应知识卡组织",'''
    assert anchor_d in src
    src = src.replace(anchor_d, new_d, 1)
    open(path, "w", encoding="utf-8").write(src)
    print("patched")

